import type { Level } from '../types';
import { CALIBRATION } from './calibration';
import { LAYOUTS } from './layouts';
import { wavesForLevel } from './waves';

/**
 * Boards come from layouts.ts (generated), waves from waves.ts, and the per-level health multiplier and threat pips from
 * calibration.ts (generated by the bot), which override the placeholders in layouts.ts. Balance numbers live in balance.ts.
 */
export const LEVELS: Level[] = LAYOUTS.map((l, i) => ({ ...l, ...CALIBRATION[i], waves: wavesForLevel(i) }));
